services = [s for s in json.decode(repo.read("services.json"))["services"] if s["enabled"]]
total = 0
for s in services:
    total += s["port"]
return {"names": sorted([s["name"] for s in services]), "ports": total}

targets = [t for t in json.decode(repo.read("deploy.json"))["targets"] if t["env"] == "prod"]
total = 0
for t in targets:
    total += t["replicas"]
return {"names": sorted([t["name"] for t in targets]), "replicas": total, "overrides": repo.read("overrides.json", missing_ok=True) != None}
